"""Exact RMControl 21.3.7 product catalogs from accepted row018 evidence.

These are app product identities, not inferred physical-remote models. A caller
must explicitly select one. Empty catalogs are retained and conflicting getter
contexts never resolve by selecting an arbitrary command.

Regenerate the compact literals with tools/generate_richmat_profiles.py. The
original APK, raw tables, and report remain machine-local.
"""

from __future__ import annotations

from dataclasses import dataclass
from functools import lru_cache
from typing import Literal, NamedTuple

type RichmatGesture = Literal["shortPress", "longPress", "shortAndLongPress", "sustainPress"]


class _ActionSpec(NamedTuple):
    action: str
    action_index: int
    short_opcode: int
    long_opcode: int
    nordic_short_opcode: int
    operate: RichmatGesture
    button: str
    short_override: int | None
    long_override: int | None
    nordic_short_override: int | None


@dataclass(frozen=True, slots=True)
class RichmatAction:
    """One ordered occurrence, including effective bytes and nullable overrides."""

    getter: str
    occurrence: int
    action: str
    action_index: int
    short_opcode: int
    long_opcode: int
    nordic_short_opcode: int
    operate: RichmatGesture
    button: str
    short_override: int | None
    long_override: int | None
    nordic_short_override: int | None

    @property
    def command_signature(self) -> tuple[int, int, int, RichmatGesture, str]:
        """Fields that must agree before collapsing duplicate occurrences."""
        return (
            self.short_opcode,
            self.long_opcode,
            self.nordic_short_opcode,
            self.operate,
            self.button,
        )


type SleepMonitoringType = Literal[
    "deviceSleepMonitoringNone", "deviceSleepMonitoringMMWifi", "deviceSleepMonitoringBle"
]
type BedLightDisplayType = Literal[
    "deviceBedLightDisplayCirclePanchromaticGamut", "deviceBedLightDisplayCircleEightColorValue"
]


class RichmatProductSettings(NamedTuple):
    """Exact initial factory metadata, not unconditional hardware capabilities."""

    richmat_sleep_monitoring_type: SleepMonitoringType
    is_richmat_forced_display_ble_sleep: bool
    is_richmat_forced_display_light_therapy: bool
    is_richmat_support_repeat_alarm: bool
    is_have_smart_lock: bool
    is_richmat_have_light_strip: bool
    is_richmat_have_groove_light_strip: bool
    is_richmat_support_light_therapy: bool
    is_richmat_support_blanket: bool
    is_richmat_have_warm_cold_strip: bool
    is_avocado_support_repeat_alarm: bool
    is_have_light_strip: bool
    bed_light_display_type: BedLightDisplayType
    is_support_repeat_alarm: bool
    rmc_sleep_monitoring_type: SleepMonitoringType
    is_have_bottom_massage_count_down: bool


@dataclass(frozen=True, slots=True)
class RichmatProductProfile:
    """A concrete selector's full ordered app catalog, including empty tables."""

    code: str
    actions: tuple[RichmatAction, ...]
    settings: RichmatProductSettings

    @property
    def getter_names(self) -> tuple[str, ...]:
        """Getter contexts in their original order."""
        return tuple(dict.fromkeys(action.getter for action in self.actions))

    def find_actions(self, action: str, *, getter: str | None = None) -> tuple[RichmatAction, ...]:
        """Return every matching occurrence; never discard duplicate positions."""
        return tuple(
            item
            for item in self.actions
            if item.action == action and (getter is None or item.getter == getter)
        )

    def resolve_action(self, action: str, *, getter: str | None = None) -> RichmatAction | None:
        """Resolve only absent ambiguity in effective bytes, gesture, and button.

        Use find_actions to distinguish an absent action from conflicting app
        contexts. Equal commands may retain different override provenance; all
        original occurrences remain available through actions and find_actions.
        """
        matches = self.find_actions(action, getter=getter)
        if not matches:
            return None
        first = matches[0]
        if any(item.command_signature != first.command_signature for item in matches[1:]):
            return None
        return first


@lru_cache(maxsize=64)
def get_product_profile(code: str) -> RichmatProductProfile | None:
    """Load an exact selector, allowing case differences but no alias inference."""
    if not code.isascii():
        return None
    normalized = code.upper()
    tables = _PRODUCT_TABLES.get(normalized)
    if tables is None:
        return None
    actions = tuple(
        RichmatAction(_GETTERS[getter_id], occurrence, *_ACTION_SPECS[spec_id])
        for getter_id, spec_ids in tables
        for occurrence, spec_id in enumerate(spec_ids)
    )
    return RichmatProductProfile(normalized, actions, _PRODUCT_SETTINGS[normalized])


